oxy_webhelp_navlinks = {"azr_storage_tiering_evaluate_options-d39536e24034":{"topics":[{"title":"Customer-controlled archival location versus RCV","shortdesc":"<p class=\"shortdesc\">A comparative overview of the customer-controlled archival location and Rubrik Cloud         Vault.<\/p>","href":"saas\/azr_customer_arch_loc_versus_rcv.html","attributes":{"data-id":"azr_customer_arch_loc_versus_rcv"},"menu":{"hasChildren":false},"tocID":"azr_customer_arch_loc_versus_rcv-d39536e24045","topics":[]},{"title":"Azure access tiers","shortdesc":"<p class=\"shortdesc\">Azure storage offers four access tiers to meet different storage         requirements.<\/p>","href":"forecast\/azure_access_tiers.html","attributes":{"data-id":"azure_access_tiers"},"menu":{"hasChildren":false},"tocID":"azure_access_tiers-d39536e24056","topics":[]},{"title":"Azure instant tiering","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> provides the capability to instantly tier the Azure virtual         machine or managed disk snapshots to the specified archival location.<\/p>","href":"saas\/azr_instant_tiering.html","attributes":{"data-id":"azr_instant_tiering"},"menu":{"hasChildren":false},"tocID":"azr_instant_tiering-d39536e24067","topics":[]},{"title":"Understand data archival and snapshot retention dynamics","shortdesc":"<p class=\"shortdesc\">Information about how Rubrik manages data archival and snapshot retention for Amazon         EC2 instances and Azure virtual machines. Understanding these dynamics is crucial for         managing storage costs and ensuring data compliance. The approach of Rubrik to archival         varies based on the archival type defined in the SLA Domain.<\/p>","href":"saas\/cloud_understand_data_arch_snap_ret_2.html","attributes":{"data-id":"cloud_understand_data_arch_snap_ret"},"menu":{"hasChildren":false},"tocID":"cloud_understand_data_arch_snap_ret-d39536e24080","topics":[]},{"title":"Private and service endpoints usage for Azure storage tiering","shortdesc":"<p class=\"shortdesc\">You can reduce data transfer costs by tiering snapshots to an Azure storage account         by using Azure private or service endpoints.<\/p>","href":"saas\/azr_private_service_endpoints_usage_archival.html","attributes":{"data-id":"azr_private_service_endpoints_usage_archival"},"menu":{"hasChildren":false},"tocID":"azr_private_service_endpoints_usage_archival-d39536e24091","topics":[]},{"title":"Supported encryption types for Azure storage tiering","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> supports three encryption types for data stored in Azure archival         locations: server-side encryption with platform-managed keys, server-side encryption with         customer-managed keys, and client-side encryption.<\/p>","href":"saas\/azr_supp_encryption_storage_tiering.html","attributes":{"data-id":"azr_supp_encryption_storage_tiering"},"menu":{"hasChildren":false},"tocID":"azr_supp_encryption_storage_tiering-d39536e24102","topics":[]},{"title":"Encryption options for Azure cloud-native archival","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> supports server-side encryption using a cloud provider—managed         key or a customer-managed key. It also supports client-side encryption using your own Azure         Key Vault key for Azure cloud-native archival locations.<\/p>","href":"saas\/azr_cnp_archival_encryption_options.html","attributes":{"data-id":"azr_cnp_archival_encryption_options"},"menu":{"hasChildren":false},"tocID":"azr_cnp_archival_encryption_options-d39536e24115","topics":[]},{"title":"Client-side encryption for Azure virtual machines","shortdesc":"<p class=\"shortdesc\">Client-side encryption protects archived Azure virtual machine data using your Azure         Key Vault key before the data leaves the Exocompute environment in your Azure subscription         and reaches cloud storage.<\/p>","href":"saas\/azr_cnp_client_side_encryption_vm.html","attributes":{"data-id":"azr_cnp_client_side_encryption_vm"},"menu":{"hasChildren":false},"tocID":"azr_cnp_client_side_encryption_vm-d39536e24128","topics":[]},{"title":"Client-side encryption for Azure Blob Storage","shortdesc":"<p class=\"shortdesc\">Client-side encryption protects archived Azure Blob Storage data using your own Azure         Key Vault key before the data leaves the Exocompute environment in your Azure subscription         and reaches cloud storage.<\/p>","href":"saas\/azr_cnp_client_side_encryption.html","attributes":{"data-id":"azr_cnp_client_side_encryption"},"menu":{"hasChildren":false},"tocID":"azr_cnp_client_side_encryption-d39536e24139","topics":[]}]}};